begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.mi(t text) returns uuid language sql immutable as $$select md5('member-self-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.mi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-self@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','candidate','foreign','unconfirmed']) t;
insert into public.organizations(id,name,slug,status) values(pg_temp.mi('org'),'Ministério fictício self','member-self-test','active'),(pg_temp.mi('other'),'Outro ministério fictício','member-self-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.mi('unit'),pg_temp.mi('org'),'Sede fictícia','sede','headquarters'),(pg_temp.mi('otherunit'),pg_temp.mi('other'),'Outra sede fictícia','sede','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) values(pg_temp.mi('ownermember'),pg_temp.mi('org'),pg_temp.mi('owner'),pg_temp.mi('unit'),'owner','active');
insert into public.people(id,organization_id,unit_id,full_name,email,status) values(pg_temp.mi('candidateperson'),pg_temp.mi('org'),pg_temp.mi('unit'),'Pessoa já cadastrada','candidate-self@example.invalid','active');
create function pg_temp.submit(d jsonb) returns jsonb language sql as $$select public.member_self_service(pg_temp.mi('org'),'submit',pg_temp.mi('unit'),d)$$;
create function pg_temp.review(u text,fields text[]) returns jsonb language sql as $$select public.member_profile_review(pg_temp.mi('org'),'review',(select id from private.member_profile_requests where organization_id=pg_temp.mi('org') and user_id=pg_temp.mi(u) and status='pending'),fields,'Conferência fictícia de identidade')$$;
select ok(not has_table_privilege('authenticated','private.member_profile_requests','select'),'fila sem leitura direta');
select ok(not has_function_privilege('anon','public.member_self_service(uuid,text,uuid,jsonb)','execute'),'visitante não altera cadastro');
set local role anon;
select is(public.member_app_config('member-self-test')->>'name','Ministério fictício self','configuração pública não exige escolha de ministério');
select ok(not public.member_app_config('member-self-test')::text like '%candidate-self%','configuração não expõe contatos de membros');
reset role;
set local role authenticated;
select pg_temp.actor('unconfirmed');
select throws_ok($$select pg_temp.submit('{"full_name":"Conta fictícia"}')$$,'42501',null,'e-mail confirmado obrigatório');
select pg_temp.actor('member');
select throws_ok($$select public.member_self_service(pg_temp.mi('org'),'submit',pg_temp.mi('otherunit'),'{"full_name":"Conta fictícia"}')$$,'42501','member_unit_denied','igreja de outro ministério recusada');
select throws_ok($$select pg_temp.submit('{"full_name":"Conta fictícia","role":"admin"}')$$,'22023','invalid_member_profile','papel administrativo não aceito');
select lives_ok($$select pg_temp.submit('{"full_name":"Pessoa fictícia app","phone":"11999999999","street":"Rua fictícia"}')$$,'cadastro enviado');
select lives_ok($$select pg_temp.submit('{"full_name":"Pessoa fictícia app","phone":"11999999999","street":"Rua fictícia"}')$$,'repetição não duplica pedido');
select throws_ok($$select pg_temp.submit('{"full_name":"Outra proposta"}')$$,'40001','member_request_pending','pedido pendente não é sobrescrito');
select is(public.member_self_service(pg_temp.mi('org'),'profile')->>'membershipStatus','active','novo usuário do app tem acesso na hora');
select is((select role::text from public.organization_memberships where organization_id=pg_temp.mi('org') and user_id=auth.uid()),'member','não promove conta');
select ok(public.member_self_service(pg_temp.mi('org'),'profile')->>'personId' is not null,'conta vinculada ao próprio cadastro sem expor outros registros');
select throws_ok($$select public.member_profile_review(pg_temp.mi('org'),'list')$$,'42501','member_review_denied','membro não revisa fila');
select pg_temp.actor('candidate');
select lives_ok($$select pg_temp.submit('{"full_name":"Nome conferido manualmente"}')$$,'duplicidade por e-mail encaminhada à revisão');
select is((select auth_user_id from public.people where id=pg_temp.mi('candidateperson')),null,'e-mail não vincula identidade automaticamente');
select is(public.member_self_service(pg_temp.mi('org'),'profile')->'profile','null'::jsonb,'candidato não recebe dados da pessoa ainda não vinculada');
select pg_temp.actor('foreign');
select is(public.member_self_service(pg_temp.mi('org'),'profile')->'profile','null'::jsonb,'outra conta não vê perfil');
select pg_temp.actor('owner');
select is(jsonb_array_length(public.member_profile_review(pg_temp.mi('org'),'list')->'items'),2,'administração vê pedidos pendentes');
reset role;
select is((select count(*)::integer from public.people where organization_id=pg_temp.mi('org') and auth_user_id=pg_temp.mi('member')),1,'repetição criou apenas um cadastro vinculado');
select lives_ok($$select pg_temp.review('member',array['full_name','phone'])$$,'aplica campos selecionados');
select is((select status from private.member_profile_requests where user_id=pg_temp.mi('member')),'partial','revisão parcial registrada');
select is((select phone from public.people where auth_user_id=pg_temp.mi('member') and organization_id=pg_temp.mi('org')),'11999999999','telefone aprovado aplicado');
select ok(not exists(select 1 from public.person_addresses a join public.people p on p.id=a.person_id where p.auth_user_id=pg_temp.mi('member')),'endereço não aprovado não aplicado');
select lives_ok($$select pg_temp.review('candidate',array['full_name'])$$,'vinculação conferida explicitamente');
select is((select auth_user_id from public.people where id=pg_temp.mi('candidateperson')),pg_temp.mi('candidate'),'cadastro anterior vinculado sem duplicar');
set local role authenticated;
select pg_temp.actor('member');
select is(public.member_self_service(pg_temp.mi('org'),'profile')->>'membershipStatus','active','aprovação libera vínculo de membro');
select lives_ok($$select pg_temp.submit('{"phone":"11888888888"}')$$,'membro pede alteração');
reset role;
update public.people set phone='11777777777' where auth_user_id=pg_temp.mi('member') and organization_id=pg_temp.mi('org');
select pg_temp.actor('owner');
select throws_ok($$select pg_temp.review('member',array['phone'])$$,'40001','member_profile_changed','revisão não sobrescreve edição administrativa recente');
select lives_ok($$select pg_temp.review('member',array[]::text[])$$,'administração pode recusar conflito');
select ok(exists(select 1 from public.audit_logs where organization_id=pg_temp.mi('org') and action='member.profile.reviewed'),'revisão auditada');
select * from finish();
rollback;
